create temporary table polish_before on commit drop as select 'app_private.battle_sessions' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.battle_sessions t) v union all select 'public.characters' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from public.characters t) v union all select 'app_private.character_active_builds' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.character_active_builds t) v union all select 'app_private.combat_content_records' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.combat_content_records t where content_key not in(select d#>>'{source,id}' from polish_targets)) v union all select 'app_private.combat_content_versions' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.combat_content_versions t where not(content_key in ('emberbrand','stormcaller-staff','twinfang-blade') and content_version=9)) v union all select 'app_private.combat_content_publications' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.combat_content_publications t where content_key not in ('emberbrand','stormcaller-staff','twinfang-blade')) v union all select 'app_private.combat_content_drafts' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\n' order by row_data),'')) digest from (select to_jsonb(t)::text row_data from app_private.combat_content_drafts t) v union all select 'app_private.combat_effect_timing_policy_versions' label,count(*) amount,md5(coalesce(string_agg(row_data,E'\