do $release$ declare x jsonb; owner_id uuid; result jsonb; begin
 if clock_timestamp()<timestamptz '2026-11-06T18:58:15.965590Z' or exists(select 1 from pg_stat_activity where pid<>pg_backend_pid() and backend_type='client backend' and xact_start<timestamptz '2026-11-06T18:25:45.965590Z') then raise exception 'NOV6_DRAIN_INCOMPLETE';end if;
 if (select count(*) from polish_targets)<>4 or (select count(*) from polish_targets where d->'publication'<>'null'::jsonb)<>3 then raise exception 'NOV6_SCOPE';end if;
 if exists(select 1 from app_private.combat_content_drafts where content_key in(select d#>>'{source,id}' from polish_targets)) then raise exception 'NOV6_OWNER_DRAFT_PRESENT';end if;
 if exists(select 1 from app_private.combat_content_versions where content_key in(select d#>>'{source,id}' from polish_targets) and content_version>=8) or exists(select 1 from app_private.runtime_item_source_definitions where item_id in(select d#>>'{source,id}' from polish_targets) and content_version>=8) then raise exception 'NOV6_VERSION_CHANGED';end if;
 for x in select d from polish_targets loop
  if app_private.current_runtime_item_v1(x#>>'{source,id}') is distinct from coalesce(nullif(x#>'{baseline,publicationDefinition}','null'::jsonb),x#>'{baseline,sourceDefinition}') then raise exception 'NOV6_PREDECESSOR_CHANGED';end if;
  if not exists(select 1 from app_private.runtime_item_source_definitions s where s.item_id=x#>>'{source,id}' and s.content_version=6 and s.definition=x#>'{baseline,sourceDefinition}') then raise exception 'NOV6_SOURCE_CHANGED';end if;
  if not exists(select 1 from app_private.combat_content_records r where r.content_key=x#>>'{source,id}' and r.content_kind='item' and r.lifecycle='active' and r.revision=(x#>>'{baseline,revision}')::bigint and r.version_floor=(x#>>'{baseline,floor}')::integer and r.builtin_version=6) then raise exception 'NOV6_RECORD_CHANGED';end if;
 end loop;
 if (select count(*) from app_private.master_panel_role_assignments where role='game-owner' and enabled)<>1 then raise exception 'NOV6_OWNER_CHANGED';end if;
 select user_id into owner_id from app_private.master_panel_role_assignments where role='game-owner' and enabled;
 perform public.seed_runtime_item_sources_v1((select jsonb_agg(d->'source' order by d#>>'{source,id}') from polish_targets));
 for x in select d from polish_targets loop
  if not exists(select 1 from app_private.runtime_item_source_definitions s where s.item_id=x#>>'{source,id}' and s.content_version=8 and s.definition=x->'source') or not exists(select 1 from app_private.combat_content_records r where r.content_key=x#>>'{source,id}' and r.revision=(x#>>'{baseline,revision}')::bigint+1 and r.version_floor=8 and r.builtin_version=8) then raise exception 'NOV6_SOURCE_READBACK';end if;
  if x->'publication'<>'null'::jsonb then
   result:=public.commit_combat_content_record_v1(owner_id,null::uuid,x#>>'{source,id}',(x#>>'{baseline,revision}')::bigint+1,x->'publication',public.read_combat_content_catalogue_token_v1(),8);
   if not exists(select 1 from app_private.combat_content_publications p join app_private.combat_content_versions v on v.id=p.version_id where p.content_key=x#>>'{source,id}' and v.content_version=9 and v.definition=jsonb_set(x->'publication','{contentVersion}','9'::jsonb)) then raise exception 'NOV6_PUBLICATION_READBACK';end if;
  end if;
 end loop;
end;$release$;
